function fmtPercent(v,d=1){if(v==null||!Number.isFinite(Number(v)))return"—";const n=Number(v)*100;return`${n>0?"+":""}${n.toFixed(d)}%`}
function fmtPrice(v){return v==null?"—":`${Math.round(v).toLocaleString("zh-CN")} 元/㎡`}
function fmtNumber(v,d=0){return v==null?"—":Number(v).toLocaleString("zh-CN",{maximumFractionDigits:d,minimumFractionDigits:d})}
function tone(v){return v==null||Math.abs(v)<.001?"":v<0?"negative":"positive"}
function escapeHTML(t){return String(t??"").replace(/[&<>\"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]))}
