async function fetchJSON(url){
  if(window.DASHBOARD_STATIC_BUILD&&window.DashboardData){
    const u=new URL(url,location.href),p=u.searchParams;
    if(u.pathname.endsWith("/api/meta"))return state.meta;
    if(u.pathname.endsWith("/api/map-config"))return{provider:"amap",configured:false,mode:"browser_fallback",service_host:""};
    if(u.pathname.endsWith("/api/communities"))return DashboardData.searchCommunities(p);
    if(u.pathname.endsWith("/api/community"))return DashboardData.communityDetail(p);
    if(u.pathname.endsWith("/api/community-heatmap"))return{config:{},summary:{eligible_count:0},rows:[]};
    if(u.pathname.endsWith("/api/community-locations"))return{locations:{}};
    if(u.pathname.endsWith("/api/analyze"))return DashboardData.analyze(p);
    if(u.pathname.endsWith("/api/trend"))return DashboardData.trend(p);
  }
  const r=await fetch(url),p=await r.json();if(!r.ok)throw new Error(p.error||`请求失败：${r.status}`);return p
}
async function postJSON(url,payload){const r=await fetch(url,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(payload)}),p=await r.json();if(!r.ok)throw new Error(p.error||`请求失败：${r.status}`);return p}
