function resetAmap(){state.communityLocationRequestId++;destroyCommunityMap();state.heatmapInfo?.close();state.heatmapMap?.destroy();state.heatmapInfo=null;state.heatmapMap=null;state.heatmapCanvas=null;state.heatmapLocated=[];state.heatmapMarkers=[];state.heatmapLabels=[];state.heatmapEventsBound=false;if(state.heatmapDrawFrame)cancelAnimationFrame(state.heatmapDrawFrame);state.heatmapDrawFrame=null;state.amap=null;state.amapLoadPromise=null;document.querySelectorAll('script[data-amap-loader="true"]').forEach(x=>x.remove());delete window.AMapLoader;delete window.AMap;delete window._AMapSecurityConfig}
