function createCommunityMap(AMap){const host=$("communityLocationMap");if(state.communityMap&&host.querySelector(".amap-container"))return state.communityMap;if(state.communityMap)destroyCommunityMap();host.innerHTML="";state.communityMap=new AMap.Map("communityLocationMap",{zoom:16,center:[116.397428,39.90923],viewMode:"2D",resizeEnable:true});state.communityMap.addControl(new AMap.Scale());state.communityMap.addControl(new AMap.ToolBar({position:{top:"12px",right:"12px"}}));return state.communityMap}
