const HEATMAP_PALETTE=[[0,[0,104,55]],[.15,[24,168,117]],[.31,[22,185,199]],[.47,[53,103,212]],[.62,[123,66,178]],[.74,[240,212,58]],[.87,[239,139,44]],[1,[199,53,46]]];
