function setupHeatmapControls(){try{$("communityHeatMode").value=localStorage.getItem("beijing-house-heatmap-mode")||"relative_gradient";$("communityHeatLabels").checked=localStorage.getItem("beijing-house-heatmap-labels")==="1"}catch{}$("communityHeatMode").onchange=()=>{try{localStorage.setItem("beijing-house-heatmap-mode",$("communityHeatMode").value)}catch{}refreshHeatmapPresentation()};$("communityHeatLabels").onchange=()=>{try{localStorage.setItem("beijing-house-heatmap-labels",$("communityHeatLabels").checked?"1":"0")}catch{}refreshHeatmapPresentation()}}
